/**
 * The fitted corner-correction coefficient tables. TRANSCRIBED FROM S2, not
 * recomputed — and deliberately so.
 *
 * Source: `spikes/s2-geometry-field/src/coefficients.ts`, itself generated by
 * that spike's `npm run fit`. The fit is an exact Chebyshev (L-inf) solve, not a
 * general optimizer: pinning the corner offset to the true corner reach makes
 * the objective linear in the coefficients, and the residual equioscillates
 * across 11 alternating extrema. The reported deviation is therefore the
 * family's capability rather than an optimizer's luck.
 *
 * These stay committed for the reason S2 gives: a table that silently moves when
 * the fitter is touched is not a regression target. `test/error-bound.test.ts`
 * asserts the declared bound against this table, so regenerating it means
 * re-deriving the bound and updating the spec's Decision Log.
 *
 * Two tables, because there are two reference curves and S2 measured that the
 * choice between them matters 6.4x more than the field family does:
 *
 *  - `FIGMA_RSUPN_TABLE` — indexed by EFFECTIVE smoothing (after the budget
 *    clamp) across the whole [0, 1] range. This is the interpolable authoring
 *    axis, and the axis the declared bound is measured on.
 *  - `APPLE_RSUPN` — one coefficient set, fit directly against Apple's measured
 *    `.continuous` corner. `profile: "continuous"` resolves to this
 *    (Decision Log #20: routing through Figma at smoothing 0.66 was measured and
 *    rejected at 6.4x the value error).
 *
 * Families C (`rsup`) and D (`rsupn`) share a zero level set and are fit
 * separately only because the normalization shifts the L-inf optimum slightly.
 */

/**
 * Number of correction terms. The basis is `s2^2 .. s2^(N+1)` where
 * `s2 = sin(2*theta)`.
 *
 * Starting at the SQUARE is not arbitrary: the true radial support has
 * `R'(0) = 0`, because the corner leaves the straight edge both tangentially and
 * with zero curvature, so any basis with a linear term in `s2` would have to
 * cancel it. Odd powers above that are included because `R` is not an even
 * function of theta about 0 — a `sin^2`-only basis converges visibly more
 * slowly.
 *
 * Order is a tuning knob, not a design commitment. Five terms give 1.38e-3 r
 * worst case with coefficients bounded by 3.3. Seven give 6.6e-4 r but push
 * coefficients to ~56, which starts to matter in f32 — at which point the
 * polynomial wants re-expressing in a Chebyshev basis rather than monomials.
 */
export const RSUP_BASIS_ORDER = 5;

export type CornerCoefficients = readonly [number, number, number, number, number];

export const ZERO_COEFFICIENTS: CornerCoefficients = [0, 0, 0, 0, 0];

export interface CoefficientRow {
  /** effective smoothing, after the budget clamp */
  readonly sEff: number;
  readonly k: CornerCoefficients;
  /** max |field| on the true contour in units of the corner radius — scale-free */
  readonly contourDevPerR: number;
}

