/**
 * Fits against Apple's actual `.continuous` corner. Apple's curve has no
 * smoothing parameter, so each is a single coefficient set. Measured at
 * 6.06e-4 r contour deviation — ~3x closer to Apple than Figma's best-matching
 * smoothing can get, and 6.4x better on band value error than routing through
 * Figma's family (0.104 px vs 0.670 px).
 *
 * The residual barely improves with a higher-order basis (6.06e-4 -> 6.02e-4 for
 * one extra term), because it is limited by Apple's own 2.4532-degree tangent
 * break rather than by the polynomial. This field is as close to Apple's curve
 * as a smooth field can usefully get.
 */
export const APPLE_RSUPN = {
  k: [0.058939, 0.53608908, -1.48273371, 1.77253595, -0.74059491] as CornerCoefficients,
  contourDevPerR: 0.000606381,
} as const;

export const APPLE_RSUP = {
  k: [0.05944375, 0.53352847, -1.47723609, 1.76689797, -0.73837656] as CornerCoefficients,
  contourDevPerR: 0.00062355,
} as const;

/**
 * Linear interpolation into a coefficient table by effective smoothing.
 *
 * Real shapes rarely land on the fit grid: the budget clamp produces arbitrary
 * effective smoothing. `test/error-bound.test.ts` asserts the bound still holds
 * at off-grid values, which is what says the 0.05 grid is dense enough.
 */
export function coefficientsAt(
  table: readonly CoefficientRow[],
  sEff: number,
): { k: CornerCoefficients; contourDevPerR: number } {
  const first = table[0];
  const last = table[table.length - 1];
  if (first === undefined || last === undefined) {
    throw new Error("empty coefficient table");
  }
  if (sEff <= first.sEff) return { k: first.k, contourDevPerR: first.contourDevPerR };
  if (sEff >= last.sEff) return { k: last.k, contourDevPerR: last.contourDevPerR };

  for (let i = 1; i < table.length; i++) {
    const lo = table[i - 1];
    const hi = table[i];
    if (lo === undefined || hi === undefined) break;
    if (sEff <= hi.sEff) {
      const u = (sEff - lo.sEff) / (hi.sEff - lo.sEff);
      const mix = (j: 0 | 1 | 2 | 3 | 4): number => lo.k[j] + u * (hi.k[j] - lo.k[j]);
      return {
        k: [mix(0), mix(1), mix(2), mix(3), mix(4)],
        contourDevPerR: lo.contourDevPerR + u * (hi.contourDevPerR - lo.contourDevPerR),
      };
    }
  }
  return { k: last.k, contourDevPerR: last.contourDevPerR };
}
